CREATE OR REPLACE FUNCTION public.accept_ride_atomic(target_ride_id UUID, acc_driver_id UUID) RETURNS JSON LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_ride public.rides%ROWTYPE; v_driver public.drivers%ROWTYPE; BEGIN SELECT * INTO v_driver FROM public.drivers d WHERE d.id = acc_driver_id AND (d.user_id = auth.uid() OR auth.role() = 'service_role') AND d.status = 'approved' AND d.is_online = true AND d.is_available = true FOR UPDATE; IF NOT FOUND THEN RETURN json_build_object('success', false, 'message', 'Driver not available.'); END IF; SELECT * INTO v_ride FROM public.rides r WHERE r.id = target_ride_id FOR UPDATE; IF NOT FOUND THEN RETURN json_build_object('success', false, 'message', 'Ride not found.'); END IF; IF v_ride.status NOT IN ('pending', 'searching') OR v_ride.driver_id IS NOT NULL THEN RETURN json_build_object('success', false, 'message', 'Ride unavailable.'); END IF; UPDATE public.rides SET driver_id = acc_driver_id, status = 'accepted', matched_at = COALESCE(matched_at, now()), updated_at = now() WHERE id = target_ride_id AND status IN ('pending', 'searching') AND driver_id IS NULL RETURNING * INTO v_ride; IF NOT FOUND THEN RETURN json_build_object('success', false, 'message', 'Ride already taken.'); END IF; UPDATE public.drivers SET is_available = false, updated_at = now() WHERE id = acc_driver_id; INSERT INTO public.ride_matching_log (ride_id, driver_id, response, responded_at) VALUES (target_ride_id, acc_driver_id, 'accepted', now()); RETURN json_build_object('success', true, 'message', 'Ride accepted.', 'ride', row_to_json(v_ride)); END; $$;